function m062dataAssert($condition,$message){if(!$condition)throw new RuntimeException($message);}
function m062dataCanonicalRateMatches($resolution,$pod,$country,$fkPort=0){if($resolution['status']!=='matched'||count($resolution['matches'])!==1)return false;$match=$resolution['matches'][0];return!empty($match['fk_port'])&&$match['port_name']===$pod&&$match['country_code']===$country&&(int)$match['fk_port']===(int)$fkPort;}
function m062dataCompositeComplete($resolution,$present){if($resolution['status']!=='matched'||count($resolution['matches'])<2)return false;$expected=array();foreach($resolution['matches']as$match)$expected[$match['country_code'].'|'.$match['port_name']]=true;$actual=array();foreach($present as$row)$actual[$row['country_code'].'|'.$row['port_name']]=true;return count($expected)===count($actual)&&count(array_diff_key($expected,$actual))===0;}
