$validatedCanonicalRates=0;$validatedRawRates=0;$rateResult=$db->query("SELECT rowid,pod,pod_raw,destination_country,fk_destination_port FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".$entity);if(!$rateResult)throw new RuntimeException('Rate-country audit query failed.');while($rate=$db->fetch_object($rateResult)){$resolution=$resolver->resolveList($rate->pod,false);m062dataAssert(m062dataCanonicalRateMatches($resolution,(string)$rate->pod,(string)$rate->destination_country,(int)$rate->fk_destination_port),'Unresolved or non-canonical port/country/id at rate row '.(int)$rate->rowid);if((string)$rate->pod_raw!==''){$rawResolution=$resolver->resolveList($rate->pod_raw,true);if(PortNameResolver::exactCatalogAliasTransition($rawResolution)){m062dataAssert(m062dataCanonicalRateMatches($rawResolution,(string)$rate->pod,(string)$rate->destination_country,(int)$rate->fk_destination_port),'Alexandria raw POD resolves to a different canonical destination at rate row '.(int)$rate->rowid);$validatedRawRates++;}}$validatedCanonicalRates++;}
$validatedCompositeSources=0;$rawResult=$db->query("SELECT DISTINCT fk_batch,source_row,COALESCE(source_cell,'') source_cell,pod_raw,container_type,shipping_line,cost_price FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".$entity." AND pod_raw IS NOT NULL AND pod_raw<>''");if(!$rawResult)throw new RuntimeException('Composite audit query failed.');while($raw=$db->fetch_object($rawResult)){$resolution=$resolver->resolveList($raw->pod_raw,true);if($resolution['status']!=='matched'||count($resolution['matches'])<2)continue;$identity="fk_batch <=> ".m062dataSqlValue($db,$raw->fk_batch)." AND source_row <=> ".m062dataSqlValue($db,$raw->source_row)." AND COALESCE(source_cell,'')='".$db->escape($raw->source_cell)."' AND container_type <=> ".m062dataSqlValue($db,$raw->container_type)." AND shipping_line <=> ".m062dataSqlValue($db,$raw->shipping_line)." AND cost_price <=> ".m062dataSqlValue($db,$raw->cost_price);$present=array();$presentResult=$db->query("SELECT pod port_name,destination_country country_code,COUNT(*) copies FROM ".MAIN_DB_PREFIX."chinaplanetsp_rate WHERE entity=".$entity." AND pod_raw='".$db->escape($raw->pod_raw)."' AND ".$identity." AND port_match_method='composite' GROUP BY pod,destination_country");if(!$presentResult)throw new RuntimeException('Composite source audit failed.');while($presentRow=$db->fetch_object($presentResult)){m062dataAssert((int)$presentRow->copies===1,'Duplicate composite destination for source '.$raw->pod_raw);$present[]=array('port_name'=>$presentRow->port_name,'country_code'=>$presentRow->country_code);}m062dataAssert(m062dataCompositeComplete($resolution,$present),'Composite destinations incomplete for source '.$raw->pod_raw.' row '.$raw->source_row);$validatedCompositeSources++;}
$destinationWarnings=0;$otherWarnings=0;$res=$db->query("SELECT rowid,warning_count,report_json FROM ".MAIN_DB_PREFIX."chinaplanetsp_batch WHERE entity=".$entity);while($batch=$db->fetch_object($res)){$report=json_decode((string)$batch->report_json,true);$warnings=is_array($report)&&isset($report['warnings'])&&is_array($report['warnings'])?$report['warnings']:array();foreach($warnings as$warning){if(preg_match('/^(?:Unmapped|Ambiguous) destination/u',$warning))$destinationWarnings++;else$otherWarnings++;}}
